SELECT COUNT(*) > 0
FROM (
    SELECT charge_impuid FROM charge WHERE charge_impuid = #{imp_uid}
    UNION ALL
    SELECT payment_impuid FROM payment WHERE payment_impuid = #{imp_uid}
) combined

SELECT charge_id as chargeId, users_id as usersId, charge_impuid as impUid, charge_merchant_uid as merchantUid, charge_method as payMethod, charge_pg_provider as pgProvider, charge_pg_tid as pgTid, charge_receipt_url as receiptUrl, charge_status as status, charge_status_detail as statusDetail, charge_amount as amount, charge_cancel_amount as cancelAmount, charge_buyer_name as buyerName, charge_buyer_email as buyerEmail, charge_buyer_tel as buyerTel, charge_fail_reason as failReason, charge_cancel_reason as cancelReason, charge_paid_at as paidAt, charge_cancelled_at as cancelledAt, charge_created_at as createdAt, charge_updated_at as updatedAt FROM charge WHERE charge_impuid = #{imp_uid}
UNION ALL
SELECT NULL as chargeId, users_id as usersId, payment_impuid as impUid, payment_merchant_uid as merchantUid, payment_method as payMethod, payment_pg_provider as pgProvider, payment_pg_tid as pgTid, payment_receipt_url as receiptUrl, payment_status as status, payment_status_detail as statusDetail, payment_amount as amount, payment_cancel_amount as cancelAmount, payment_buyer_name as buyerName, payment_buyer_email as buyerEmail, payment_buyer_tel as buyerTel, payment_fail_reason as failReason, payment_cancel_reason as cancelReason, payment_paid_at as paidAt, payment_cancelled_at as cancelledAt, payment_created_at as createdAt, payment_updated_at as updatedAt FROM payment WHERE payment_impuid = #{imp_uid}
LIMIT 1

